'use strict';

// MODULES //

var tape = require( 'tape' );
var isFunction = require( '@stdlib/assert/is-function' );
var isUint32Array = require( '@stdlib/assert/is-uint32array' );
var Float64Array = require( '@stdlib/array/float64' );
var Uint32Array = require( '@stdlib/array/uint32' );
var factory = require( './../lib/factory.js' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.ok( isFunction( factory ), 'main export is a function' );
	t.end();
});

tape( 'factory returns a function', function test( t ) {
	var rng = factory();
	t.ok( isFunction( rng ), 'returns a function' );
	t.end();
});

tape( 'factory accepts seed option', function test( t ) {
	var rng;

	rng = factory({
		'seed': 1234
	});
	t.ok( isFunction( rng ), 'returns function with seed option' );

	rng = factory({
		'seed': 0
	});
	t.ok( isFunction( rng ), 'returns function with seed 0' );

	rng = factory({
		'seed': 0xffffffff
	});
	t.ok( isFunction( rng ), 'returns function with max seed' );

	t.end();
});

tape( 'factory accepts state option', function test( t ) {
	var state;
	var rng1 = factory({
		'seed': 1234
	});
	var rng2;
	state = rng1.state;

	rng2 = factory({
		'state': state
	});
	t.ok( isFunction( rng2 ), 'returns function with state option' );
	t.end();
});

tape( 'factory accepts copy option', function test( t ) {
	var state;
	var rng1 = factory({
		'seed': 5678
	});
	var rng2;
	var rng3;
	state = rng1.state;

	rng2 = factory({
		'state': state,
		'copy': true
	});
	t.ok( isFunction( rng2 ), 'returns function with copy=true' );

	rng3 = factory({
		'state': state,
		'copy': false
	});
	t.ok( isFunction( rng3 ), 'returns function with copy=false' );

	t.end();
});

tape( 'factory with copy=false does not copy state', function test( t ) {
	var state = new Uint32Array( 4 );
	var rng = factory({
		'state': state,
		'copy': false
	});

	// When copy=false, modifications to original state should eventually affect RNG
	state[ 0 ] = 9999;

	t.ok( isFunction( rng ), 'returns function with copy=false' );
	t.end();
});

tape( 'factory with copy=true copies state', function test( t ) {
	var original = new Uint32Array( 4 );
	var state1;
	var state2;
	var rng = factory({
		'state': original,
		'copy': true
	});
	state1 = rng.state;
	state2 = rng.state;

	t.strictEqual( state1[ 0 ], state2[ 0 ], 'state not affected by modifying original' );
	t.end();
});

tape( 'factory returns PRNG with correct NAME', function test( t ) {
	var rng = factory({
		'seed': 1234
	});
	t.strictEqual( rng.NAME, 'xorshift128+', 'NAME is "xorshift128+"' );
	t.end();
});

tape( 'factory returns PRNG with normalized method', function test( t ) {
	var rng = factory({
		'seed': 2345
	});
	t.ok( isFunction( rng.normalized ), 'has normalized method' );
	t.end();
});

tape( 'factory returns PRNG with copy method', function test( t ) {
	var rng = factory({
		'seed': 3456
	});
	t.ok( isFunction( rng.copy ), 'has copy method' );
	t.end();
});

tape( 'factory returns PRNG with toJSON method', function test( t ) {
	var rng = factory({
		'seed': 4567
	});
	t.ok( isFunction( rng.toJSON ), 'has toJSON method' );
	t.end();
});

tape( 'factory returns PRNG with seed getter', function test( t ) {
	var rng = factory({
		'seed': 5678
	});
	t.ok( typeof rng.seed === 'number', 'seed is accessible' );
	t.end();
});

tape( 'factory returns PRNG with state getter/setter', function test( t ) {
	var state;
	var rng = factory({
		'seed': 6789
	});

	t.ok( isUint32Array( rng.state ), 'state getter works' );

	state = new Uint32Array( 4 );
	state[ 0 ] = 1000;
	state[ 1 ] = 2000;
	state[ 2 ] = 3000;
	state[ 3 ] = 4000;

	rng.state = state;
	t.ok( isUint32Array( rng.state ), 'state setter works' );
	t.end();
});

tape( 'factory throws TypeError when options is not an object', function test( t ) {
	var values;
	var i;

	values = [ 'invalid', 123, [] ];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws on invalid options '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			factory( value );
		};
	}
});

tape( 'factory throws TypeError when seed is invalid', function test( t ) {
	var values;
	var i;

	values = [ -1, 3.14, 'invalid', {} ];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badSeed( values[i] ), TypeError, 'throws on invalid seed '+values[i] );
	}
	t.end();

	function badSeed( value ) {
		return function badSeed() {
			factory({
				'seed': value
			});
		};
	}
});

tape( 'factory throws TypeError when state is not Uint32Array', function test( t ) {
	var values;
	var i;

	values = [ [], new Float64Array( 4 ), {} ];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badState( values[i] ), TypeError, 'throws on invalid state '+values[i] );
	}
	t.end();

	function badState( value ) {
		return function badState() {
			factory({
				'state': value
			});
		};
	}
});

tape( 'factory throws RangeError when state has wrong length', function test( t ) {
	var values;
	var i;

	values = [
		new Uint32Array( 0 ),
		new Uint32Array( 2 ),
		new Uint32Array( 8 )
	];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badRange( values[i] ), RangeError, 'throws on wrong state length' );
	}
	t.end();

	function badRange( value ) {
		return function badRange() {
			factory({
				'state': value
			});
		};
	}
});

tape( 'factory throws TypeError when copy is not boolean', function test( t ) {
	var values;
	var i;

	values = [ 'true', 1, null ];

	for ( i = 0; i < values.length; i++ ) {
		t.throws( badCopy( values[i] ), TypeError, 'throws on invalid copy '+values[i] );
	}
	t.end();

	function badCopy( value ) {
		return function badCopy() {
			factory({
				'seed': 1234,
				'copy': value
			});
		};
	}
});

tape( 'factory without options uses random seed', function test( t ) {
	var rng1 = factory();
	var rng2 = factory();
	var v1 = rng1();
	var v2 = rng2();

	// Very unlikely to be equal if truly random
	t.notEqual( v1, v2, 'different random seeds produce different outputs' );
	t.end();
});

tape( 'factory with same seed produces deterministic sequence', function test( t ) {
	var rng1 = factory({
		'seed': 12345
	});
	var rng2 = factory({
		'seed': 12345
	});
	var i;

	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( rng1(), rng2(), 'same seed at iteration ' + i );
	}
	t.end();
});

tape( 'factory with state produces deterministic continuation', function test( t ) {
	var state;
	var rng1 = factory({
		'seed': 54321
	});
	var rng2;
	var i;

	// Generate and skip values
	for ( i = 0; i < 50; i++ ) {
		rng1();
	}

	// Save state
	state = rng1.state;

	// Create second PRNG with same state
	rng2 = factory({
		'state': state
	});

	// Verify same continuation
	for ( i = 0; i < 100; i++ ) {
		t.strictEqual( rng1(), rng2(), 'same state continuation at iteration ' + i );
	}
	t.end();
});

tape( 'factory creates independent PRNGs', function test( t ) {
	var rng1 = factory({
		'seed': 1111
	});
	var rng3 = factory({
		'seed': 2222
	});
	var v1 = rng1();
	var v3 = rng3();

	t.notEqual( v1, v3, 'different seeds produce different output' );
	t.end();
});

tape( 'factory output is 32-bit unsigned integer', function test( t ) {
	var rng = factory({
		'seed': 99999
	});
	var v;
	var i;

	for ( i = 0; i < 100; i++ ) {
		v = rng();
		t.ok( v >= 0, 'output >= 0' );
		t.ok( v <= 0xffffffff, 'output <= 2^32-1' );
		t.ok( Number.isInteger( v ), 'output is integer' );
	}
	t.end();
});

tape( 'factory normalized output is in [0,1)', function test( t ) {
	var rng = factory({
		'seed': 88888
	});
	var v;
	var i;

	for ( i = 0; i < 100; i++ ) {
		v = rng.normalized();
		t.ok( v >= 0, 'normalized output >= 0' );
		t.ok( v < 1, 'normalized output < 1' );
	}
	t.end();
});

tape( 'factory state length is always 4', function test( t ) {
	var rng1 = factory();
	var rng2 = factory({
		'seed': 1234
	});
	var rng3 = factory({
		'state': new Uint32Array( 4 )
	});

	t.strictEqual( rng1.state.length, 4, 'random seed state length is 4' );
	t.strictEqual( rng2.state.length, 4, 'seeded PRNG state length is 4' );
	t.strictEqual( rng3.state.length, 4, 'state-initialized PRNG state length is 4' );
	t.end();
});

tape( 'factory state is Uint32Array', function test( t ) {
	var rng1 = factory();
	var rng2 = factory({
		'seed': 1234
	});
	var rng3 = factory({
		'state': new Uint32Array( 4 )
	});

	t.ok( isUint32Array( rng1.state ), 'random seed state is Uint32Array' );
	t.ok( isUint32Array( rng2.state ), 'seeded PRNG state is Uint32Array' );
	t.ok( isUint32Array( rng3.state ), 'state-initialized PRNG state is Uint32Array' );
	t.end();
});
